#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
struct FlowSolver {
    struct Edge {
        int v, capacity, rev;
    };
    vector<vector<Edge>> graph;
    vector<int> dist, ptr;
    int source, sink;
    FlowSolver(int V, int s, int t): graph(V), dist(V), ptr(V), source(s), sink(t) {}
    void addEdge(int u, int v, int cap) {
        graph[u].push_back({v, cap, (int)graph[v].size()});
        graph[v].push_back({u, 0, (int)graph[u].size() - 1});
    }
    bool bfs() {
        fill(dist.begin(), dist.end(), -1);
        dist[source]=0;
        queue<int>q; q.push(source);
        while(!q.empty()){
            int u=q.front(); q.pop();
            for(auto &e:graph[u]){
                if(e.capacity>0 && dist[e.v]<0){
                    dist[e.v]=dist[u]+1;
                    q.push(e.v);
                }
            }
        }
        return dist[sink]>=0;
    }
    int dfs(int u, int flow) {
        if(u==sink) return flow;
        for(int &i=ptr[u]; i<(int)graph[u].size(); i++){
            auto &e=graph[u][i];
            if(e.capacity>0 && dist[e.v]==dist[u]+1){
                int pushed=dfs(e.v, min(flow, e.capacity));
                if(pushed>0){
                    e.capacity-=pushed;
                    graph[e.v][e.rev].capacity+=pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }
    long long computeMaxFlow() {
        long long total=0;
        while(bfs()){
            fill(ptr.begin(), ptr.end(), 0);
            while(int flow=dfs(source, INT_MAX)){
                total+=flow;
            }
        }
        return total;
    }
};

int n, t, ck[15][15];
string grid[15], es[15];
int y, x;
int dy[]={1, -1, 0, 0};
int dx[]={0, 0, 1, -1};
void search()
{
    queue<pair<int,int>>q; q.push({y,x});
    ck[y][x]=1;
    int level=1;
    while(!q.empty()){
        int size=q.size();
        for(int i=0; i<size; i++){
            auto now=q.front(); q.pop();
            for(int dir=0; dir<4; dir++){
                int ny=now.first+dy[dir];
                int nx=now.second+dx[dir];
                if(ny<0 || ny>=n || nx<0 || nx>=n) continue;
                if(ck[ny][nx] || grid[ny][nx]=='Y') continue;
                ck[ny][nx]=level;
                q.push({ny,nx});
            }
        }
        ++level;
        level=min(level, t);
    }
}
int node_map[15][15][65];
int main()
{
    cin>>n>>t;
    for(int i=0; i<n; i++){
        cin>>grid[i];
        for(int j=0; j<n; j++){
            if(grid[i][j]=='Z') y=i, x=j;
        }
    }
    getline(cin, grid[n]);
    getline(cin, grid[n]);
    for(int i=0; i<n; i++){
        cin>>es[i];
    }
    search();
    int total_nodes=0;
    for(int i=0; i<n; i++){
        for(int j=0; j<n; j++){
            if('0'<=grid[i][j] && grid[i][j]<='9'){
                if(ck[i][j]==0) ck[i][j]=t;
                for(int t_idx=0; t_idx<ck[i][j]; t_idx++){
                    node_map[i][j][t_idx]=++total_nodes;
                }
            }
            if('1'<=es[i][j] && es[i][j]<='9'){
                node_map[i][j][ck[i][j]]=++total_nodes;
            }
        }
    }
    int INF=1e9;
    int s=0, e=total_nodes+3;
    FlowSolver flow(total_nodes+5, s, e);
    for(int i=0; i<n; i++){
        for(int j=0; j<n; j++){
            if('1'<=grid[i][j] && grid[i][j]<='9'){
                flow.addEdge(s, node_map[i][j][0], grid[i][j]-'0');
            }
            for(int dir=0; dir<4; dir++){
                int ny=i+dy[dir], nx=j+dx[dir];
                if(ny<0 || ny>=n || nx<0 || nx>=n) continue;
                if(grid[ny][nx]=='Y' || grid[ny][nx]=='Z') continue;
                for(int t_idx=0; ; t_idx++){
                    if(node_map[i][j][t_idx]==0) break;
                    if(t_idx==ck[i][j] && es[i][j]>='1' && es[i][j]<='9') break;
                    if(node_map[ny][nx][t_idx+1]){
                        flow.addEdge(node_map[i][j][t_idx], node_map[ny][nx][t_idx+1], INF);
                    }
                }
            }
            if('1'<=es[i][j] && es[i][j]<='9'){
                for(int t_idx=0; t_idx<ck[i][j]; t_idx++){
                    flow.addEdge(node_map[i][j][t_idx], node_map[i][j][t_idx+1], INF);
                }
                flow.addEdge(node_map[i][j][ck[i][j]], e, es[i][j]-'0');
            }
        }
    }
    int answer=flow.computeMaxFlow();
    cout<<answer<<endl;
}
